import clientPromise from '@/lib/mongodb';

export async function getSalesAnalytics() {
  const client = await clientPromise;
  const db = client.db('tienda');

  const pipeline = [
    // 1. Filtrar órdenes pagadas del último mes
    { $match: { status: 'PAID', createdAt: { $gte: new Date(Date.now() - 30 * 86400000) } } },
    // 2. Desglosar productos individuales
    { $unwind: '$items' },
    // 3. Agrupar por categoría de producto y sumar ventas
    {
      $group: {
        _id: '$items.category',
        totalRevenue: { $sum: { $multiply: ['$items.price', '$items.qty'] } },
        unitsSold: { $sum: '$items.qty' }
      }
    },
    // 4. Ordenar por mayor facturación
    { $sort: { totalRevenue: -1 } }
  ];

  return db.collection('orders').aggregate(pipeline).toArray();
}

import { Redis } from '@upstash/redis';
import { User } from '@/models/User';

const redis = Redis.fromEnv();

export async function getUserWithCache(userId: string) {
  const cacheKey = `user:${userId}`;

  // 1. Intentar leer de Redis (Memoria)
  const cached = await redis.get(cacheKey);
  if (cached) return cached;

  // 2. Si hay Cache Miss, consultar MongoDB
  const user = await User.findById(userId).lean();
  if (!user) return null;

  // 3. Guardar en Redis con TTL de 60 segundos
  await redis.set(cacheKey, JSON.stringify(user), { ex: 60 });
  return user;
}

