if (process.env.NODE_ENV === 'development') {
  // En desarrollo, usa una variable global para preservar la conexión entre HMR
  let globalWithMongo = global as typeof globalThis & { _mongoClientPromise?: Promise<MongoClient> };
  if (!globalWithMongo._mongoClientPromise) {
    client = new MongoClient(uri);
    globalWithMongo._mongoClientPromise = client.connect();
  }
  clientPromise = globalWithMongo._mongoClientPromise;
} else {
  // En producción, crea una nueva instancia reutilizable
  client = new MongoClient(uri);
  clientPromise = client.connect();
}

