import { useEffect, useState } from 'react';
import { io, Socket } from 'socket.io-client';

export function LiveChat() {
  const [messages, setMessages] = useState<string[]>([]);
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    const newSocket = io(process.env.NEXT_PUBLIC_SOCKET_URL || 'http://localhost:4000');
    setSocket(newSocket);

    newSocket.on('chat_message', (msg: string) => {
      setMessages((prev) => [...prev, msg]);
    });

    return () => {
      newSocket.disconnect();
    };
  }, []);

  const sendMessage = (text: string) => {
    socket?.emit('send_message', text);
  };

  return <div>{messages.map((m, i) => <p key={i}>{m}</p>)}</div>;
}

export async function GET() {
  const encoder = new TextEncoder();

  const stream = new ReadableStream({
    start(controller) {
      let count = 0;
      const interval = setInterval(() => {
        count++;
        const data = `data: ${JSON.stringify({ message: 'Evento en vivo', count, time: Date.now() })}\n\n`;
        controller.enqueue(encoder.encode(data));
        if (count >= 10) {
          clearInterval(interval);
          controller.close();
        }
      }, 1000);
    }
  });

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache, no-transform',
      'Connection': 'keep-alive',
    },
  });
}

async function startLongPolling(onData: (data: any) => void) {
  let active = true;

  while (active) {
